-- Sync to the phone (docs/phone-budget.md section 8, decisions.md D-44). Every change to a table the phone keeps
-- (src/sync-tables.ts) is logged here by a trigger: one row per changed row, with a number that only goes up, so
-- GET /api/sync?since=N can send exactly what changed. Rows are never deleted from change_log. Expand-only.
CREATE TABLE change_log (
  tbl TEXT NOT NULL,
  pk TEXT NOT NULL,                  -- JSON array of the row's primary key values
  seq INTEGER NOT NULL,
  deleted INTEGER NOT NULL,
  PRIMARY KEY (tbl, pk)
) WITHOUT ROWID;
CREATE INDEX change_log_seq ON change_log (seq);
-- Offline edits sent again after a dropped answer are applied once (docs/phone-budget.md section 12).
CREATE TABLE edit_seen (
  id TEXT PRIMARY KEY,
  at INTEGER NOT NULL
) WITHOUT ROWID;
-- A transaction that took another row's key (pending to posted, a manual row matched): edits sent offline to the
-- old key land on the new one.
CREATE TABLE txn_key_move (
  old_key TEXT PRIMARY KEY,
  new_key TEXT NOT NULL,
  at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE TRIGGER budget_sync_ins AFTER INSERT ON budget BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('budget', json_array(NEW.id), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 0) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 0; END;
CREATE TRIGGER budget_sync_upd AFTER UPDATE ON budget BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('budget', json_array(NEW.id), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 0) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 0; END;
CREATE TRIGGER budget_sync_key AFTER UPDATE OF id ON budget WHEN OLD.id IS NOT NEW.id BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('budget', json_array(OLD.id), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 1) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 1; END;
CREATE TRIGGER budget_sync_del AFTER DELETE ON budget BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('budget', json_array(OLD.id), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 1) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 1; END;
