CREATE TRIGGER setting_sync_key AFTER UPDATE OF budget_id, key ON setting WHEN OLD.budget_id IS NOT NEW.budget_id OR OLD.key IS NOT NEW.key BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('setting', json_array(OLD.budget_id, OLD.key), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 1) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 1; END;
CREATE TRIGGER setting_sync_del AFTER DELETE ON setting BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('setting', json_array(OLD.budget_id, OLD.key), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 1) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 1; END;
CREATE TRIGGER health_status_sync_ins AFTER INSERT ON health_status BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('health_status', json_array(NEW.budget_id, NEW.key), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 0) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 0; END;
CREATE TRIGGER health_status_sync_upd AFTER UPDATE ON health_status BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('health_status', json_array(NEW.budget_id, NEW.key), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 0) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 0; END;
CREATE TRIGGER health_status_sync_key AFTER UPDATE OF budget_id, key ON health_status WHEN OLD.budget_id IS NOT NEW.budget_id OR OLD.key IS NOT NEW.key BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('health_status', json_array(OLD.budget_id, OLD.key), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 1) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 1; END;
CREATE TRIGGER health_status_sync_del AFTER DELETE ON health_status BEGIN INSERT INTO change_log (tbl, pk, seq, deleted) VALUES ('health_status', json_array(OLD.budget_id, OLD.key), (SELECT coalesce(max(seq), 0) + 1 FROM change_log), 1) ON CONFLICT (tbl, pk) DO UPDATE SET seq = excluded.seq, deleted = 1; END;
